// ContestDbContext.cs:66-74 — raw file I/O in EF Core DbContext
public async Task<byte[]> ExportDatabaseAsync()
{
    var path = "contest.db";
    if (File.Exists(path))
    {
        return await File.ReadAllBytesAsync(path);
    }
    return Array.Empty<byte>();
}

// ContestDbContext.cs:76-79 — raw file I/O in EF Core DbContext
public async Task ImportDatabaseAsync(byte[] data)
{
    var path = "contest.db";
    await File.WriteAllBytesAsync(path, data);
}

