// Program.cs:7 — Web imports the Services extension
using ContestJudging.Services.Extensions;

// Program.cs:64 — Web wraps Services DI in a local function (does not move composition root)
static void AddServices(IServiceCollection services) { services.AddContestJudgingServices("Data Source=contest.db"); }

// ServiceCollectionExtensions.cs:33 — only LinearSpacingScoring is registered
services.AddScoped<IScoringStrategy, LinearSpacingScoring>();

// PercentileScoring.cs exists and is tested (ScoringStrategyTests) but never wired in DI
// DefinedIntervalScoring.cs exists and is tested (ScoringStrategyTests) but never wired in DI
// DefinedIntervalScoring also has a parameterized constructor (IEnumerable<double> rankPoints)
// which cannot be registered via simple AddScoped<,> — needs a factory registration

// ServiceCollectionExtensions.cs:23 — AddDbContext registers as Scoped by default
services.AddDbContext<ContestDbContext>(options => options.UseSqlite(connectionString));

// In Blazor WASM, Scoped == Singleton unless OwningComponentBase is used.
// The codebase never uses OwningComponentBase.
// All 8 service registrations use AddScoped.
//
// EF Core DbContext accumulates tracked entities in the ChangeTracker.
// A DbContext living for the entire browser session will:
//   - Grow the change tracker with every Add/Update/Delete operation
//   - Never release memory for discarded entities
//   - Degrade SaveChangesAsync performance over time
//
// Program.cs:21 — SQLitePCL.Batteries_V2.Init() happens once at startup, so
// EnsureCreatedAsync (line 56) only runs once, but the DbContext persists forever.

